package client

import (
	"crypto/ecdsa"
	"crypto/sha256"
	"crypto/x509"
	"encoding/base64"
	"encoding/pem"
	"os"
	"strings"
	"time"

	pb "github.com/github/authnd/client/proto/authentication/v0"
	"github.com/github/go-stats"
	jwt "github.com/golang-jwt/jwt/v5"
	"github.com/pkg/errors"
)

// NewExchangeTokenVerifier creates a new ExchangeTokenVerifier
// which is capable of verifying the authenticity of a stateless
// token generated by the authnd TokenExchanger service.
//
// Requires the presence a list of public keys, which are used to
// used to verify the token's signature, in the TOKEN_EXCHANGER_PUBLIC_KEYS
// environment variable federated from the authnd Vault.
func NewExchangeTokenVerifier(opts ...Option) (*ExchangeTokenVerifier, error) {
	clientOpts := defaultClientOptions()
	err := applyOptions(clientOpts, opts...)
	if err != nil {
		return nil, errors.Wrap(err, "error applying options")
	}

	clientStatter := clientOpts.Statter.WithTags(stats.Tags{
		clientVersionDimensionName: Version,
		serviceDimensionName:       "TokenExchanger",
	})

	// Create a multiStatsClient to ensure that all stats emitted from this middleware
	// are available without a prefix, so all service show up under the same set of metrics.
	//
	// We need to leave the initial statter (with client-defined prefix) in place to ensure
	// we don't break any client-side observability.
	statter := &multiStatsClient{
		clients: []stats.Client{
			clientStatter,               // includes a client-defined prefix
			clientStatter.SetPrefix(""), // omits any client-defined prefix
		},
	}

	publicKeysEnv, ok := os.LookupEnv("TOKEN_EXCHANGER_PUBLIC_KEYS")
	if !ok {
		return nil, errors.New("TOKEN_EXCHANGER_PUBLIC_KEYS environment variable is required")
	}

	publicKeys := make(map[string]*ecdsa.PublicKey)
	for _, publicKeyData := range strings.Split(publicKeysEnv, ";") {
		publicKey, err := loadPublicKey(publicKeyData)
		if err != nil {
			return nil, errors.Wrap(err, "error loading public key")
		}

		fingerprint, err := generatePublicKeyFingerprint(publicKeyData)
		if err != nil {
			return nil, errors.Wrap(err, "error generating public key fingerprint")
		}

		statter.Counter("authnd.client.token_verifier.public_key_loaded", stats.Tags{"kid": fingerprint}, 1)
		publicKeys[fingerprint] = publicKey
	}

	return &ExchangeTokenVerifier{
		keys:    publicKeys,
		statter: statter,
	}, nil

}

func loadPublicKey(publicKeyData string) (*ecdsa.PublicKey, error) {
	decoded, err := base64.StdEncoding.DecodeString(publicKeyData)
	if err != nil {
		return nil, errors.Wrap(err, "error decoding public key")
	}

	pemDecoded, _ := pem.Decode(decoded)
	if pemDecoded == nil {
		return nil, errors.New("public key is not in PEM format")
	}

	key, err := x509.ParsePKIXPublicKey(pemDecoded.Bytes)
	if err != nil {
		return nil, errors.Wrap(err, "error parsing public key")
	}

	publicKey, ok := key.(*ecdsa.PublicKey)
	if !ok {
		return nil, errors.New("public key is not an ECDSA key")
	}
	return publicKey, nil
}

func generatePublicKeyFingerprint(publicKeyData string) (string, error) {
	b64 := []byte(publicKeyData)
	key := make([]byte, base64.StdEncoding.DecodedLen(len(b64)))
	n, err := base64.StdEncoding.Decode(key, b64)
	if err != nil {
		return "", errors.Wrapf(err, "cannot decode public key %q", publicKeyData)
	}

	sha256sum := sha256.Sum256(key[:n])
	return base64.RawStdEncoding.EncodeToString(sha256sum[:]), nil
}

type ExchangeTokenVerifier struct {
	keys    map[string]*ecdsa.PublicKey
	statter stats.Client
}

func (v *ExchangeTokenVerifier) VerifyToken(plaintext string) ([]*pb.Attribute, error) {
	start := time.Now()
	result := "failed"
	keyID := "unknown"
	defer func() {
		v.statter.Distribution(
			"authnd.client.token_verifier.verify_token_ns",
			stats.Tags{"result": result, "kid": keyID},
			float64(time.Since(start).Nanoseconds()),
		)
	}()

	var claims ExchangeTokenClaims
	token, err := jwt.ParseWithClaims(plaintext, &claims, func(token *jwt.Token) (interface{}, error) {
		if token == nil || token.Header == nil {
			return nil, errors.New("token is missing header")
		}
		kid, ok := token.Header["kid"]
		if !ok {
			v.statter.Counter("authnd.client.token_verifier.unexpected_kid", stats.Tags{"kid": keyID}, 1)
			return nil, errors.New("kid header is missing")
		}
		keyID = kid.(string)

		key, ok := v.keys[keyID]
		if !ok {
			return nil, errors.New("kid header does not match registered public key(s)")
		}
		return key, nil
	})
	// TODO(chriskirkland): do we need to intercept sentinel errors from jwt library (e.g. jwt.ErrTokenExpired)?
	if err != nil {
		return nil, errors.Wrap(err, "failed to parse token")
	}

	if !token.Valid {
		return nil, errors.New("invalid token")
	}
	result = "success"
	return claims.toProto(), nil
}
